import assert from "node:assert/strict";
import { test } from "node:test";
import { formatUsdMicro } from "../src/money.ts";

test("grader: formatUsdMicro", () => {
  assert.equal(formatUsdMicro(1_234_567), "USD 1.23");
  assert.equal(formatUsdMicro(1_235_000), "USD 1.24");
  assert.equal(formatUsdMicro(1_500_000), "USD 1.50");
  assert.equal(formatUsdMicro(0), "USD 0.00");
  assert.equal(formatUsdMicro(-500_000), "USD -0.50");
  assert.equal(formatUsdMicro(999_999), "USD 1.00");
  assert.throws(() => formatUsdMicro(1.5), TypeError);
});

