export const MICRO_PER_USD = 1_000_000;

export function formatUsdMicro(micro: number): string {
  if (!Number.isInteger(micro)) throw new TypeError("amount must be an integer number of micro-units");
  const sign = micro < 0 ? "-" : "";
  const abs = Math.abs(micro);
  const cents = Math.floor((abs + 5_000) / 10_000);
  const dollars = Math.floor(cents / 100);
  const rest = cents % 100;
  return `USD ${sign}${dollars}.${String(rest).padStart(2, "0")}`;
}

